-- Sprint 05.3.2.4 — verification\n-- READ-ONLY.\nselect jsonb_pretty(jsonb_build_object(\n  'finalizer_definition', (\n    select pg_get_functiondef(p.oid)\n    from pg_proc p\n    join pg_namespace n on n.oid = p.pronamespace\n    where n.nspname = 'public'\n      and p.proname = 'finalize_player_account_provisioning_batch'\n    limit 1\n  ),\n  'synthetic', jsonb_build_object(\n    'digit_only_to_e164', ('+' || '380501234567') = '+380501234567',\n    'plus_e164_unchanged', '+380501234567' = '+380501234567'\n  )\n)) as sprint_05_3_2_4_verification;\n